// Pack pkg/dev-extension/seed/ into seed.generated.ts.
//
// The agent pod is made from nothing by the extension when it loads - a ConfigMap of these files
// and a Deployment running stock node over them - so the files have to travel inside the bundle.
// They are real files under `seed/` rather than strings in a .ts, so they are linted, diffed and
// read like the scripts they are; this bakes them.
//
//   node scripts/gen-seed.mjs
//
// The generated file is committed, so ordinary builds never run this.
//
// Why this script exists at all: it did not, and the two copies drifted. `seed/shell.sh` and the
// `shell.sh` inside `seed.generated.ts` are the same script, and with nothing to regenerate from
// the only way to change the pod was to edit both by hand and hope - which is why changing a pane
// was written down as "blocked on another repository". It is not: the source is here, the
// artifact is here, and this is the fifteen lines between them. Its sibling generators are
// gen-agent-seed.mjs and gen-dev-api.mjs, which do the same for their own artifacts.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const SEED = path.join(here, '..', 'pkg', 'dev-extension', 'seed');
const OUT = path.join(here, '..', 'pkg', 'dev-extension', 'seed.generated.ts');

// shell.sh un-flattens skill directories with the separator this product's pods use. The token
// is in the source so the script reads as what it is, and is filled here so the pod gets a
// literal. A leftover token is an error rather than a file that half works: see below.
const SUBSTITUTIONS = { __PATH_SEPARATOR__: '__' };

function podFile(file) {
  let contents = fs.readFileSync(file, 'utf8');

  for (const [token, value] of Object.entries(SUBSTITUTIONS)) {
    contents = contents.split(token).join(value);
  }

  const leftover = contents.match(/__[A-Z_]+__/);

  if (leftover) {
    throw new Error(`${ path.basename(file) } still has ${ leftover[0] } in it; add it to SUBSTITUTIONS.`);
  }

  return contents;
}

/**
 * Every file of the seed, by the name the pod knows it as.
 *
 * `seed/agent/boot.sh` is the pod's `boot.sh`: the directory is how this repository keeps the
 * agent pod's own files apart from the ones every pane shares, and the pod has one flat /seed.
 * A name that appears in both places is a mistake rather than a merge, so it is refused.
 */
function files() {
  const found = {};

  const take = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const full = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        take(full);
        continue;
      }
      if (found[entry.name]) {
        throw new Error(`Two files are called ${ entry.name }; /seed is flat, so one would win silently.`);
      }
      found[entry.name] = podFile(full);
    }
  };

  take(SEED);

  return Object.fromEntries(Object.entries(found).sort(([a], [b]) => a.localeCompare(b)));
}

const body = Object.entries(files())
  .map(([name, contents]) => `  ${ JSON.stringify(name) }: ${ JSON.stringify(contents) },`)
  .join('\n');

fs.writeFileSync(OUT, [
  '/* eslint-disable */',
  '// Generated by scripts/gen-seed.mjs from pkg/dev-extension/seed. Do not edit.',
  'export const AGENT_FILES: Record<string, string> = {',
  body,
  '};',
  '',
].join('\n'));

console.log(`seed: ${ Object.keys(files()).length } files -> ${ path.relative(path.join(here, '..'), OUT) }`); // eslint-disable-line no-console
